// Full client-side Markdown parser helper
function parseMarkdown(src) {
  if (!src) return '';
  // Normalize line endings
  src = src.replace(/\r\n|\r/g, '\n');
  
  var lines = src.split('\n');
  var out = [];
  var inCode = false;
  var codeLang = '';
  var codeBuf = [];
  var inTable = false;
  var tableHeaders = [];
  var tableAligns = [];
  var tableRows = [];
  var inList = null; // 'ul' or 'ol'
  var listStack = [];
  var inQuote = false;
  var quoteBuf = [];

  function flushQuote() {
    if (inQuote) {
      out.push('blockquote', quoteBuf.join('\n'));
      quoteBuf = [];
      inQuote = false;
    }
  }

  function flushList() {
    if (inList) {
      out.push('end_' + inList);
      inList = null;
    }
  }

  function flushTable() {
    if (inTable) {
      out.push('table', { headers: tableHeaders, aligns: tableAligns, rows: tableRows });
      inTable = false;
      tableHeaders = []; tableAligns = []; tableRows = [];
    }
  }

  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];

    // Code blocks ```
    if (/^\s*```/.test(line)) {
      if (inCode) {
        out.push('code', { lang: codeLang, code: codeBuf.join('\n') });
        inCode = false;
        codeBuf = [];
      } else {
        flushQuote(); flushList(); flushTable();
        inCode = true;
        codeLang = line.replace(/^\s*```/, '').trim();
      }
      continue;
    }

    if (inCode) {
      codeBuf.push(line);
      continue;
    }

    // Tables | col | col |
    if (/^\s*\|/.test(line) && line.trim().endsWith('|')) {
      var cells = line.trim().replace(/^\||\|$/g, '').split('|').map(function(c){ return c.trim(); });
      if (!inTable) {
        // Check if next line is divider |---|---|
        if (i + 1 < lines.length && /^\s*\|?\s*:?-+:?\s*(\||\s*$)/.test(lines[i+1])) {
          flushQuote(); flushList();
          inTable = true;
          tableHeaders = cells;
          var divLine = lines[i+1].trim().replace(/^\||\|$/g, '').split('|');
          tableAligns = divLine.map(function(d){
            d = d.trim();
            if (d.startsWith(':') && d.endsWith(':')) return 'center';
            if (d.endsWith(':')) return 'right';
            return 'left';
          });
          i++; // skip divider line
          continue;
        }
      } else {
        tableRows.push(cells);
        continue;
      }
    } else if (inTable) {
      flushTable();
    }

    // Blockquotes >
    if (/^\s*>/.test(line)) {
      flushList(); flushTable();
      inQuote = true;
      quoteBuf.push(line.replace(/^\s*>\s?/, ''));
      continue;
    } else if (inQuote) {
      flushQuote();
    }

    // Headings #
    var headMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headMatch) {
      flushList(); flushTable();
      out.push('heading', { depth: headMatch[1].length, text: headMatch[2].trim() });
      continue;
    }

    // Horizontal Rule ---
    if (/^\s*([-*_]\s*){3,}\s*$/.test(line)) {
      flushList(); flushTable();
      out.push('hr', null);
      continue;
    }

    // Lists (- * + 1.)
    var ulMatch = line.match(/^(\s*)([*+-])\s+(.*)$/);
    var olMatch = line.match(/^(\s*)(\d+[\.\)])\s+(.*)$/);
    if (ulMatch || olMatch) {
      flushTable();
      var listType = ulMatch ? 'ul' : 'ol';
      var text = ulMatch ? ulMatch[3] : olMatch[3];
      if (inList !== listType) {
        flushList();
        out.push('start_' + listType);
        inList = listType;
      }
      out.push('li', text);
      continue;
    } else if (inList && /^\s*$/.test(line)) {
      flushList();
      continue;
    } else if (inList && !/^\s+/.test(line)) {
      flushList();
    }

    // Blank line
    if (/^\s*$/.test(line)) {
      out.push('blank', null);
      continue;
    }

    // Paragraph text
    out.push('p', line);
  }

  flushQuote(); flushList(); flushTable();
  if (inCode) out.push('code', { lang: codeLang, code: codeBuf.join('\n') });

  // Render AST items to HTML
  var html = [];
  var currentP = [];

  function flushP() {
    if (currentP.length > 0) {
      html.push('<p>' + inlineFormat(currentP.join('<br>')) + '</p>');
      currentP = [];
    }
  }

  for (var k = 0; k < out.length; k += 2) {
    var type = out[k];
    var val = out[k+1];

    if (type === 'p') {
      currentP.push(val);
    } else {
      flushP();
      if (type === 'heading') {
        html.push('<h' + val.depth + '>' + inlineFormat(val.text) + '</h' + val.depth + '>');
      } else if (type === 'hr') {
        html.push('<hr>');
      } else if (type === 'blockquote') {
        html.push('<blockquote>' + parseMarkdown(val) + '</blockquote>');
      } else if (type === 'code') {
        var langAttr = val.lang ? ' class="language-' + n(val.lang) + '"' : '';
        html.push('<div class="qa-code-block"><div class="qa-code-header"><span>' + n(val.lang || 'code') + '</span><button class="qa-copy-btn" onclick="copyCode(this)">Copy</button></div><pre><code' + langAttr + '>' + n(val.code) + '</code></pre></div>');
      } else if (type === 'start_ul') {
        html.push('<ul>');
      } else if (type === 'start_ol') {
        html.push('<ol>');
      } else if (type === 'end_ul') {
        html.push('</ul>');
      } else if (type === 'end_ol') {
        html.push('</ol>');
      } else if (type === 'li') {
        html.push('<li>' + inlineFormat(val) + '</li>');
      } else if (type === 'table') {
        var tHtml = '<div class="qa-table-wrap"><table class="table table-bordered table-striped"><thead><tr>';
        for (var h = 0; h < val.headers.length; h++) {
          var align = val.aligns[h] ? ' style="text-align:' + val.aligns[h] + '"' : '';
          tHtml += '<th' + align + '>' + inlineFormat(val.headers[h]) + '</th>';
        }
        tHtml += '</tr></thead><tbody>';
        for (var r = 0; r < val.rows.length; r++) {
          tHtml += '<tr>';
          for (var c = 0; c < val.rows[r].length; c++) {
            var align = val.aligns[c] ? ' style="text-align:' + val.aligns[c] + '"' : '';
            tHtml += '<td' + align + '>' + inlineFormat(val.rows[r][c]) + '</td>';
          }
          tHtml += '</tr>';
        }
        tHtml += '</tbody></table></div>';
        html.push(tHtml);
      }
    }
  }
  flushP();

  return html.join('\n');
}

function inlineFormat(str) {
  if (!str) return '';
  // Protect code spans
  var codeSpans = [];
  str = str.replace(/`([^`]+)`/g, function(m, g1) {
    codeSpans.push(n(g1));
    return '___CODESPAN_' + (codeSpans.length - 1) + '___';
  });

  // Links [text](url)
  str = str.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(m, txt, url) {
    var safeUrl = n(url.trim());
    return '<a href="' + safeUrl + '" target="_blank" rel="noopener" class="qa-link">' + inlineFormat(txt) + '</a>';
  });

  // Bold & Italic ***text*** or ___text___
  str = str.replace(/(\*\*\*|___)(.*?)\1/g, '<strong><em>$2</em></strong>');
  // Bold **text** or __text__
  str = str.replace(/(\*\*|__)(.*?)\1/g, '<strong>$2</strong>');
  // Italic *text* or _text_
  str = str.replace(/(\*|_)(.*?)\1/g, '<em>$2</em>');

  // Restore code spans
  str = str.replace(/___CODESPAN_(\d+)___/g, function(m, id) {
    return '<code class="qa-inline-code">' + codeSpans[parseInt(id, 10)] + '</code>';
  });

  return str;
}

var markedObj = {
  parse: function(src) {
    return parseMarkdown(src);
  }
};

return markedObj;
